  quiz: [{ q: 'Koľko štátnych symbolov má Slovensko?', o: ['Štyri', 'Dva', 'Šesť'], k: 0, w: 'Znak, vlajka, pečať a hymna.' }, { q: 'Akej farby je štít v štátnom znaku?', o: ['Červenej', 'Modrej', 'Zelenej'], k: 0, w: 'Štít je červený, trojvršie modré.' }, { q: 'Ktorá vlajka je štátnou vlajkou SR?', o: ['Biela, modrá, červená so štátnym znakom', 'Biela, modrá, červená bez znaku', 'Modrá so žltými hviezdami'], k: 0, w: 'Štátny znak patrí na vlajku. Modrá s hviezdami je vlajka EÚ.' }, { q: 'Ktorá pieseň je štátnou hymnou?', o: ['Nad Tatrou sa blýska', 'Tancuj, tancuj', 'Pásla ovečky'], k: 0, w: 'Hymnou sú prvé dve slohy piesne Nad Tatrou sa blýska.', l: 2 }],
